modes.detail:
// ============ 用负数表示根，这个设计很妙 ============
//
// 数组里每个位置存一个整数，含义看正负：
//
//     parent[i] = 3   →  i 的父亲是 3
//     parent[i] = -1  →  i 是根，这个集合有 1 个元素（只有它自己）
//     parent[i] = -4  →  i 是根，这个集合有 4 个元素
//
// 为什么用负数而不是另开一个数组存"集合大小"？
//
//   ① 省一个数组；
//   ② **判断根只需要看一个数**：`parent[i] < 0` 就是根，不用再查别的表；
//   ③ 合并时也方便：两个根的大小就是两个负数，加起来直接得到新大小。
//
// 这是个典型的"用一个字段表达两层含义"的技巧。代价是可读性稍差，
// 所以注释一定要写清楚。
//
// ============ 初始状态 ============
//
// 一开始谁和谁都没关系，所以**每个元素各自成一个集合**：
//
//     下标:   0   1   2   3   4
//     parent: -1  -1  -1  -1  -1
//             ↑全部是根，每个集合只有自己
//
// 注意这里用的是 0 起始的下标，和堆那种"从 1 开始"不一样 ——
// 并查集的元素编号本来就是任意的，直接用 0..n-1 最省事。

// 最大元素个数
#define MaxSize 1000

// 并查集：一个数组 + 元素个数
typedef struct
{
// parent[i] >= 0 是父亲下标；< 0 表示它是根，绝对值是集合大小
    int *parent;
// 元素个数
    int n;
} DisjSet;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 建一个含 n 个元素的并查集，每个元素各自一组
// 这个函数和结构定义放一起，因为它就是"结构的一部分"。
DisjSet *InitSet(int n)
{
// 分配结构
    DisjSet *S = (DisjSet *)malloc(sizeof(DisjSet));
// 分配数组
    int i;

    S->parent = (int *)malloc(n * sizeof(int));
    S->n = n;

// 每个元素都置 -1：自己是根，集合大小为 1
    for (i = 0; i < n; i++)
    {
        S->parent[i] = -1;
    }

// 返回
    return S;
}

