    for (int i = 0; i < 6; i++) printf("%d ", S->parent[i]);
    printf("\n");

    Union(S, Find(S, 2), Find(S, 3));
    Union(S, Find(S, 4), Find(S, 5));
    printf("再合并 2-3 和 4-5: ");
    for (int i = 0; i < 6; i++) printf("%d ", S->parent[i]);
